        <div class="editor-form-group"><label><span class="num">9</span> 性別</label><div class="editor-radio-row"><label v-for="opt in genderOptions" :key="opt.value" class="editor-radio-item" :class="{ selected: editorDraft.gender === opt.value }"><input type="radio" :value="opt.value" v-model="editorDraft.gender"><span class="custom-radio"></span><span>{{ opt.label }}</span></label></div></div>
