        <div class="editor-form-group"><label><span class="num">11</span> 年齢②</label><div class="editor-inline-row"><input v-model="editorDraft.age2" type="number" min="0" max="100" class="editor-input" placeholder="年齢"><span class="editor-unit-text">歳</span></div></div>
        <div class="editor-form-group"><label><span class="num">12</span> 年齢③</label><div class="editor-inline-row"><input v-model="editorDraft.age3" type="number" min="0" max="100" class="editor-input" placeholder="年齢"><span class="editor-unit-text">歳</span></div></div>
