        <div class="editor-form-group"><label><span class="num">14</span> ターゲット②</label><button type="button" class="editor-trigger" @click="openTargetModal(2)"><span v-if="editorDraft.target2.length">{{ editorDraft.target2.join(' / ') }}</span><span v-else class="editor-placeholder">選択</span></button></div>
        <div class="editor-form-group"><label><span class="num">15</span> ターゲット③</label><button type="button" class="editor-trigger" @click="openTargetModal(3)"><span v-if="editorDraft.target3.length">{{ editorDraft.target3.join(' / ') }}</span><span v-else class="editor-placeholder">選択</span></button></div>
        <div class="editor-form-group"><label><span class="num">16</span> デバイス</label><div class="editor-radio-row"><label v-for="opt in deviceOptions" :key="opt.value" class="editor-radio-item" :class="{ selected: editorDraft.device === opt.value }"><input type="radio" :value="opt.value" v-model="editorDraft.device"><span class="custom-radio"></span><span>{{ opt.label }}</span></label></div></div>
        <div class="editor-form-group editor-form-group-wide"><label><span class="num">17</span> 備考</label><textarea v-model="editorDraft.notes" class="editor-input editor-textarea" rows="4" placeholder="補足事項があれば入力してください"></textarea></div>
      </div><div class="modal-footer editor-modal-footer"><button type="button" class="back-btn" @click="closeEditorModal">キャンセル</button><button type="button" class="next-btn animated-btn visible editor-save-btn" :disabled="!isEditorValid" @click="savePattern"><span>{{ editorMode === 'new' ? 'テーブルに追加' : '変更を保存' }}</span><span class="btn-arrow">&rarr;</span></button></div></div></div>

      <div v-if="isModalOpen" class="modal-overlay" @click.self="closePrefModal"><div class="modal-content youtube-modal-content"><div class="modal-header"><h3>都道府県を選択</h3><button type="button" class="btn-close" @click="closePrefModal">×</button></div><div class="modal-toolbar"><input v-model="prefSearch" type="search" placeholder="都道府県を検索"><button type="button" @click="clearPrefSelection">クリア</button></div><div class="modal-selected-header">選択済み</div><div class="modal-selected-body"><span v-for="name in selectedPrefNames" :key="name" class="selected-chip">{{ name }} <button type="button" @click="removePref(name)">×</button></span><span v-if="!selectedPrefNames.length" class="empty-selected">未選択</span></div><div class="modal-options-header">都道府県</div><div class="pref-grid"><button v-for="pref in filteredPrefList" :key="pref.id" type="button" class="pref-option" :class="{ selected: selectedPrefNames.includes(pref.name) }" @click="togglePref(pref)">{{ pref.name }}</button></div><div class="modal-footer"><button type="button" class="back-btn" @click="closePrefModal">キャンセル</button><button type="button" class="back-btn modal-confirm-btn" @click="confirmPrefSelection">確定</button></div></div></div>

      <div v-if="targetModalOpen" class="modal-overlay" @click.self="closeTargetModal"><div class="modal-content youtube-modal-content"><div class="modal-header"><h3>{{ targetModalTitle }}</h3><button type="button" class="btn-close" @click="closeTargetModal">×</button></div><div class="modal-toolbar"><input v-model="targetSearch" type="search" placeholder="ターゲットを検索"><button type="button" @click="clearTargetSelection">クリア</button></div><div class="modal-selected-header">選択済み</div><div class="modal-selected-body"><span v-for="value in selectedTargetValues" :key="value" class="selected-chip">{{ value }} <button type="button" @click="removeTarget(value)">×</button></span><span v-if="!selectedTargetValues.length" class="empty-selected">未選択</span></div><div class="modal-options-header">候補</div><div class="target-option-list"><button v-for="value in filteredTargetOptions" :key="value" type="button" class="target-option" :class="{ selected: selectedTargetValues.includes(value) }" @click="toggleTarget(value)">{{ value }}</button></div><div class="modal-footer"><button type="button" class="back-btn" @click="closeTargetModal">キャンセル</button><button type="button" class="back-btn modal-confirm-btn" @click="confirmTargetSelection">確定</button></div></div></div>
