<script setup>
import { reactive, computed, ref, onMounted } from 'vue'
import { DotLottieVue } from '@lottiefiles/dotlottie-vue'
const currentStep = ref(1), activeFieldIndex = ref(1), hoveredPlatform = ref(null), applicantNameInput = ref(null)
const lottieRefs = reactive({})
onMounted(() => { if (applicantNameInput.value) applicantNameInput.value.focus() })
const formData = reactive({ applicantName:'', department:'', email:'', clientName:'', projectName:'', dueDate:'', remarks:'' })
let patternSeq = 1
const clonePattern = (pattern) => JSON.parse(JSON.stringify(pattern))
const createEmptyPattern = (platformId='youtube') => ({ id:`${platformId}-${Date.now()}-${patternSeq++}`, platformId, menu:'', placement:'', verticalCreative:'', horizontalCreative:'', periodNumber:null, periodUnit:'日', budget:null, prefId:'', prefName:'', prefNames:[], city:'', gender:'all', age1:'', age2:'', age3:'', target1:[], target2:[], target3:[], device:'all', notes:'' })
const platformPatterns = reactive({ meta:[], listing:[], youtube:[] })
const youtubeMenus = ['VRC2.0（リーチ）','VVC（視聴）','スキップ不可','目標FQ（マルチフォーマット）','目標FQ（スキップ可）','目標FQ（スキップ不可）']
const placementOptionsByMenu = { 'VRC2.0（リーチ）':['インストリーム','バンパー','インフィード','ショート'], 'VVC（視聴）':['インストリーム','インフィード','ショート'], 'スキップ不可':['インストリーム'], '目標FQ（マルチフォーマット）':['インストリーム','バンパー','インフィード','ショート'], '目標FQ（スキップ可）':['インストリーム','バンパー'], '目標FQ（スキップ不可）':['インストリーム'] }
const videoLengthOptions = [{value:'なし',text:'なし'},{value:'6s＊バンパー',text:'6s＊バンパー'},{value:'15s',text:'15s'},{value:'30s',text:'30s'},{value:'45s',text:'45s'},{value:'60s',text:'60s'},{value:'90s',text:'90s'},{value:'120s',text:'120s'}]
const restrictedVideoLengthOptions = [{value:'なし',text:'なし'},{value:'15s',text:'15s'},{value:'30s ※CTVのみ',text:'30s ※CTVのみ'},{value:'6sバンパー+15s ※β版',text:'6sバンパー+15s ※β版'}]
const getPlacementOptions = (menu) => placementOptionsByMenu[menu] || []
const getCreativeOptions = (pattern) => pattern.placement === 'バンパー' ? [{value:'6s＊バンパー',text:'6s＊バンパー'}] : (pattern.menu === 'スキップ不可' || pattern.menu === '目標FQ（スキップ不可）') ? restrictedVideoLengthOptions : videoLengthOptions
const onMenuChange = (pattern) => { const allowed=getPlacementOptions(pattern.menu); if(!allowed.includes(pattern.placement)){pattern.placement='';pattern.verticalCreative='';pattern.horizontalCreative=''}else onPlacementChange(pattern) }
const onPlacementChange = (pattern) => { const valid=getCreativeOptions(pattern).map(opt=>opt.value); if(!valid.includes(pattern.verticalCreative))pattern.verticalCreative=''; if(!valid.includes(pattern.horizontalCreative))pattern.horizontalCreative='' }
const editorModalOpen=ref(false), editorMode=ref('new'), editorPlatformId=ref('youtube'), editorIndex=ref(null), editorDraft=ref(createEmptyPattern('youtube')), activePlatformId=ref('youtube')
const selectedPlatformList=computed(()=>platformList.filter(platform=>platforms[platform.id]?.selected))
const activePlatform=computed(()=>platformList.find(platform=>platform.id===activePlatformId.value)||null)
const activePlatformName=computed(()=>activePlatform.value?.name||'Platform')
const activePatterns=computed(()=>platformPatterns[activePlatformId.value]||[])
const isYoutubeEditor=computed(()=>editorPlatformId.value==='youtube')
const genderOptions=[{value:'all',label:'すべて'},{value:'male',label:'男性'},{value:'female',label:'女性'}]
