const openNewPattern=(platformId)=>{if(!platformId||!platforms[platformId]?.selected)return;activePlatformId.value=platformId;editorPlatformId.value=platformId;editorMode.value='new';editorIndex.value=null;editorDraft.value=createEmptyPattern(platformId);editorModalOpen.value=true}
const openEditPattern=(platformId,index)=>{const row=platformPatterns[platformId]?.[index];if(!row)return;activePlatformId.value=platformId;editorPlatformId.value=platformId;editorMode.value='edit';editorIndex.value=index;editorDraft.value=clonePattern(row);editorModalOpen.value=true}
