const savePattern=()=>{if(!isEditorValid.value)return;const saved=clonePattern(editorDraft.value);saved.platformId=editorPlatformId.value;if(!platformPatterns[editorPlatformId.value])platformPatterns[editorPlatformId.value]=[];if(editorMode.value==='edit'&&editorIndex.value!==null)platformPatterns[editorPlatformId.value].splice(editorIndex.value,1,saved);else platformPatterns[editorPlatformId.value].push(saved);activePlatformId.value=editorPlatformId.value;closeEditorModal()}
